//! Conformance suite driven by the reference vectors in `tests/vectors.json`
//! (generated by `examples/gen_vectors.rs`). Per SPEC §14, decoding these vectors
//! correctly is what makes an implementation "conforming".

use laquna::{decode, DecodeError};
use serde_json::Value;

/// The vectors are embedded at compile time so the test never depends on the CWD.
const VECTORS: &str = include_str!("vectors.json");

fn from_hex(s: &str) -> Vec<u8> {
    hex::decode(s).expect("vectors.json fields must be valid hex")
}

fn parse_vectors() -> Value {
    serde_json::from_str(VECTORS).expect("tests/vectors.json must be valid JSON")
}

fn expected_error(v: &Value) -> DecodeError {
    match v["error"].as_str().expect("expected.error must be a string") {
        "InputTooShort" => DecodeError::InputTooShort,
        "InvalidVersion" => {
            let n = v["version"].as_u64().expect("InvalidVersion needs a version field");
            DecodeError::InvalidVersion(u8::try_from(n).expect("version byte fits in u8"))
        }
        "DecompressionFailed" => DecodeError::DecompressionFailed,
        "EmptySeed" => DecodeError::EmptySeed,
        other => panic!("unknown expected error kind: {other}"),
    }
}

/// Every Schema A artifact decodes, under its seed, to the listed plaintext.
#[test]
fn schema_a_decodes_to_plaintext() {
    let root = parse_vectors();
    let vectors = root["schema_a"].as_array().expect("schema_a must be an array");
    assert!(!vectors.is_empty(), "schema_a must not be empty");

    for v in vectors {
        let name = v["name"].as_str().unwrap_or("<unnamed>");
        let artifact = from_hex(v["artifact_hex"].as_str().unwrap());
        let seed = from_hex(v["seed_hex"].as_str().unwrap());
        let expected_plaintext = from_hex(v["plaintext_hex"].as_str().unwrap());

        let recovered = decode(&artifact, &seed)
            .unwrap_or_else(|e| panic!("schema_a '{name}' failed to decode: {e:?}"));
        assert_eq!(recovered, expected_plaintext, "schema_a '{name}' plaintext mismatch");
    }
}

/// Every Schema B artifact yields the listed error variant under its seed.
#[test]
fn schema_b_yields_expected_errors() {
    let root = parse_vectors();
    let vectors = root["schema_b"].as_array().expect("schema_b must be an array");
    assert!(!vectors.is_empty(), "schema_b must not be empty");

    for v in vectors {
        let name = v["name"].as_str().unwrap_or("<unnamed>");
        let artifact = from_hex(v["artifact_hex"].as_str().unwrap());
        let seed = from_hex(v["seed_hex"].as_str().unwrap());
        let expected = expected_error(&v["expected"]);

        assert_eq!(
            decode(&artifact, &seed),
            Err(expected),
            "schema_b '{name}' error mismatch"
        );
    }
}

/// Distinctness relations asserted by SPEC §16 Schema A: a distinct slug or a distinct
/// seed over the same plaintext must produce a distinct artifact.
#[test]
fn schema_a_distinctness_relations() {
    let root = parse_vectors();
    let vectors = root["schema_a"].as_array().unwrap();
    let artifact_hex = |name: &str| -> String {
        vectors
            .iter()
            .find(|v| v["name"].as_str() == Some(name))
            .unwrap_or_else(|| panic!("missing schema_a vector '{name}'"))["artifact_hex"]
            .as_str()
            .unwrap()
            .to_string()
    };

    assert_ne!(
        artifact_hex("hello_world"),
        artifact_hex("hello_world_slug2"),
        "distinct slugs must produce distinct artifacts"
    );
    assert_ne!(
        artifact_hex("hello_world"),
        artifact_hex("hello_world_seed2"),
        "distinct seeds must produce distinct artifacts"
    );
}
